const PointerSchema = z
  .object({
    type: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The alias type, can be: EMAIL|PHONE_NUMBER|IBAN.',
        readOnly: false,
        writeOnly: false,
      }),
    value: z
      .string()
      .exactOptional()
      .openapi({ description: 'The alias value.', readOnly: false, writeOnly: false }),
    name: z
      .string()
      .exactOptional()
      .openapi({ description: 'The alias name.', readOnly: false, writeOnly: false }),
    service: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The pointer service. Only required for external counterparties.',
        readOnly: false,
        writeOnly: true,
      }),
  })
  .openapi({ required: [] })
  .openapi('Pointer')

type LabelMonetaryAccountType = {
  iban?: string
  display_name?: string
  avatar?: z.infer<typeof AvatarSchema>
  label_user?: z.infer<typeof LabelUserSchema>
  country?: string
  bunq_me?: z.infer<typeof PointerSchema>
  is_light?: boolean
  swift_bic?: string
  swift_account_number?: string
  transferwise_account_number?: string
  transferwise_bank_code?: string
  merchant_category_code?: string
}

const LabelMonetaryAccountSchema: z.ZodType<LabelMonetaryAccountType> = z
  .object({
    iban: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The IBAN of the monetary account.',
        readOnly: true,
        writeOnly: false,
      }),
    display_name: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The name to display with this monetary account.',
        readOnly: true,
        writeOnly: false,
      }),
    avatar: AvatarSchema.exactOptional().openapi({
      description: 'The avatar of the monetary account.',
      readOnly: true,
      writeOnly: false,
    }),
    label_user: LabelUserSchema.exactOptional().openapi({
      description: 'The user this monetary account belongs to.',
      readOnly: true,
      writeOnly: false,
    }),
    country: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The country of the user. Formatted as a ISO 3166-1 alpha-2 country code.',
        readOnly: true,
        writeOnly: false,
      }),
    bunq_me: PointerSchema.exactOptional().openapi({
      description: 'Bunq.me pointer with type and value.',
      readOnly: true,
      writeOnly: false,
    }),
    is_light: z
      .boolean()
      .exactOptional()
      .openapi({
        description: 'Whether or not the monetary account is light.',
        readOnly: true,
        writeOnly: false,
      }),
    swift_bic: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The BIC used for a SWIFT payment.',
        readOnly: true,
        writeOnly: false,
      }),
    swift_account_number: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The account number used for a SWIFT payment. May or may not be an IBAN.',
        readOnly: true,
        writeOnly: false,
      }),
    transferwise_account_number: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The account number used for a Transferwise payment. May or may not be an IBAN.',
        readOnly: true,
        writeOnly: false,
      }),
    transferwise_bank_code: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The bank code used for a Transferwise payment. May or may not be a BIC.',
        readOnly: true,
        writeOnly: false,
      }),
    merchant_category_code: z
      .string()
      .exactOptional()
      .openapi({ description: 'The merchant category code.', readOnly: true, writeOnly: false }),
  })
  .openapi({ required: [] })
  .openapi('LabelMonetaryAccount')

const AttachmentUrlSchema = z
