const PaymentSchema: z.ZodType<PaymentType> = z
  .lazy(() =>
    z
      .object({
        amount: AmountSchema.exactOptional().openapi({
          description:
            'The Amount transferred by the Payment. Will be negative for outgoing Payments and positive for incoming Payments (relative to the MonetaryAccount indicated by monetary_account_id).',
          readOnly: false,
          writeOnly: false,
        }),
        counterparty_alias: LabelMonetaryAccountSchema.exactOptional().openapi({
          description:
            'The LabelMonetaryAccount containing the public information of the other (counterparty) side of the Payment.',
          readOnly: false,
          writeOnly: false,
        }),
        description: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'The description for the Payment. Maximum 140 characters for Payments to external IBANs, 9000 characters for Payments to only other bunq MonetaryAccounts.',
            readOnly: false,
            writeOnly: false,
          }),
        attachment: z
          .array(AttachmentMonetaryAccountPaymentSchema)
          .exactOptional()
          .openapi({
            description: 'The Attachments attached to the Payment.',
            readOnly: false,
            writeOnly: false,
          }),
        merchant_reference: z
          .string()
          .exactOptional()
          .openapi({
            description: 'Optional data included with the Payment specific to the merchant.',
            readOnly: false,
            writeOnly: false,
          }),
        allow_bunqto: z
          .boolean()
          .exactOptional()
          .openapi({
            description: 'Whether or not sending a bunq.to payment is allowed.',
            readOnly: false,
            writeOnly: true,
          }),
        id: z
          .int()
          .exactOptional()
          .openapi({
            description: 'The id of the created Payment.',
            readOnly: true,
            writeOnly: false,
          }),
        created: z
          .string()
          .exactOptional()
          .openapi({
            description: 'The timestamp when the Payment was done.',
            readOnly: true,
            writeOnly: false,
          }),
        updated: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'The timestamp when the Payment was last updated (will be updated when chat messages are received).',
            readOnly: true,
            writeOnly: false,
          }),
        monetary_account_id: z
          .int()
          .exactOptional()
          .openapi({
            description:
              'The id of the MonetaryAccount the Payment was made to or from (depending on whether this is an incoming or outgoing Payment).',
            readOnly: true,
            writeOnly: false,
          }),
        alias: LabelMonetaryAccountSchema.exactOptional().openapi({
          description:
            "The LabelMonetaryAccount containing the public information of 'this' (party) side of the Payment.",
          readOnly: true,
          writeOnly: false,
        }),
        type: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'The type of Payment, can be BUNQ, EBA_SCT, EBA_SDD, IDEAL, SWIFT or FIS (card).',
            readOnly: true,
            writeOnly: false,
          }),
        sub_type: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'The sub-type of the Payment, can be PAYMENT, WITHDRAWAL, REVERSAL, REQUEST, BILLING, SCT, SDD or NLO.',
            readOnly: true,
            writeOnly: false,
          }),
        payment_arrival_expected: PaymentArrivalExpectedSchema.exactOptional().openapi({
          description: 'Information about the expected arrival of the payment.',
          readOnly: true,
          writeOnly: false,
        }),
        bunqto_status: z
          .string()
          .exactOptional()
          .openapi({
            description: 'The status of the bunq.to payment.',
            readOnly: true,
            writeOnly: false,
          }),
        bunqto_sub_status: z
          .string()
          .exactOptional()
          .openapi({
            description: 'The sub status of the bunq.to payment.',
            readOnly: true,
            writeOnly: false,
          }),
        bunqto_share_url: z
          .string()
          .exactOptional()
          .openapi({
            description: 'The status of the bunq.to payment.',
            readOnly: true,
            writeOnly: false,
          }),
        bunqto_expiry: z
          .string()
          .exactOptional()
          .openapi({
            description: 'When bunq.to payment is about to expire.',
            readOnly: true,
            writeOnly: false,
          }),
        bunqto_time_responded: z
          .string()
          .exactOptional()
          .openapi({
            description: 'The timestamp of when the bunq.to payment was responded to.',
            readOnly: true,
            writeOnly: false,
          }),
        batch_id: z
          .int()
          .exactOptional()
          .openapi({
            description: 'The id of the PaymentBatch if this Payment was part of one.',
            readOnly: true,
            writeOnly: false,
          }),
        scheduled_id: z
          .int()
          .exactOptional()
          .openapi({
            description: 'The id of the JobScheduled if the Payment was scheduled.',
            readOnly: true,
            writeOnly: false,
          }),
        address_shipping: AddressSchema.exactOptional().openapi({
          description: 'A shipping Address provided with the Payment, currently unused.',
          readOnly: true,
          writeOnly: false,
        }),
        address_billing: AddressSchema.exactOptional().openapi({
          description: 'A billing Address provided with the Payment, currently unused.',
          readOnly: true,
          writeOnly: false,
        }),
        geolocation: GeolocationSchema.exactOptional().openapi({
          description: 'The Geolocation where the Payment was done from.',
          readOnly: true,
          writeOnly: false,
        }),
        request_reference_split_the_bill: z
          .array(RequestInquiryReferenceSchema)
          .exactOptional()
          .openapi({
            description:
              'The reference to the object used for split the bill. Can be RequestInquiry or RequestInquiryBatch',
            readOnly: true,
            writeOnly: false,
          }),
        balance_after_mutation: AmountSchema.exactOptional().openapi({
          description: 'The new balance of the monetary account after the mutation.',
          readOnly: true,
          writeOnly: false,
        }),
        payment_auto_allocate_instance: PaymentAutoAllocateInstanceSchema.exactOptional().openapi({
          description: 'A reference to the PaymentAutoAllocateInstance if it exists.',
          readOnly: true,
          writeOnly: false,
        }),
        payment_suspended_outgoing: PaymentSuspendedOutgoingSchema.exactOptional().openapi({
          description: 'A reference to the PaymentSuspendedOutgoing if it exists.',
          readOnly: true,
          writeOnly: false,
        }),
        payment_fee: PaymentFeeSchema.exactOptional().openapi({
          description: 'Incurred fee for the payment.',
          readOnly: true,
          writeOnly: false,
        }),
      })
      .openapi({ required: [] }),
  )
  .openapi('Payment')

